import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"蹇","description":"高岛易断 - 蹇","frontmatter":{"title":"蹇","description":"高岛易断 - 蹇"},"headers":[],"relativePath":"zh/classics/takashima/039.md","filePath":"zh/classics/takashima/039.md"}'),i={name:"zh/classics/takashima/039.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h2 id="蹇-1" tabindex="-1">蹇 <a class="header-anchor" href="#蹇-1" aria-label="Permalink to “蹇”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>蹇：利西南，不利东北，利见大人，贞吉。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《坎》位北，《艮》位东北，天气由北而东，而南，而西；日月出于东，没于西，天之行也。卦体内《艮》外《坎》，自东而北，逆天而行，是以为《蹇》。《蹇》自《睽》来，《艮》《坎》位在东北，《兑》《离》位在西南，就东北之本位，则难上加难，故“不利”，就西南，是《睽》位，则可以济难，故“利”。且东北而西南为顺天，顺天者必利。“大人”，即《离》明继照之大人也，明足济《蹇》，故“利见”。道得其贞，吉无不利。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山上有水，蹇，君子以反身修德。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>山上有水为《蹇》，《蹇》反卦《解》，《解》之《象》曰“雷雨作”。雷雨自上而降，雨降则山上之水必随而降，则《蹇》可解矣。君子法之“以反身修德”，不忧其《蹇》之难解，惟虑其德之未修。《坎》为悔，有反悔之意焉；《艮》为慎，有德之义焉。孟子曰，“行有不得者，反求诸其身而已矣”，此之谓也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：运当艰难，宜加奋勉，方可出险。</p><p>○　问战征：入山穷水，复杂之地，进退两难，宜率六军，戮力向西南进攻，方可获利。</p><p>○　问功名：坎险《艮》止，功名有阻，返身加勉，五年后至上爻，《象》曰“利见大人，以从贵也”，成名可望。</p><p>○　问营商：水在山上，则水蓄而不流，有财不流通之象，营商者难之。</p><p>○　问家宅：此宅傍山，防有山上来水冲落，致损墙屋，宜改易其朝向，乃利。</p><p>○　问婚姻：山水本两相为偶，山下水高则为失偶，故有《蹇》。不成则已，成亦必有反悔。</p><p>○　问疾病：《蹇》为足疾，涉水登山，必不能往行也。</p><p>○　问失物：宜反从身上寻之。</p><p>○　问讼事：宜自返而罢讼，吉。</p><p>○　问行人：被中途发水所阻，大有险难，他日空身可归。</p><p>○　问六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻居《艮》之下，当《蹇》之始，“往蹇”者，往就《蹇》地。在初去上《蹇》犹远，可以不往，乃不避险阻，敢于犯难。在六爻之初，能首倡赴义，开“朋来”之先，声闻嘉誉。《象传》曰“宜待也”，以为轻身尝试，徒博一时之誉，不如审机观变，待时而动，斯得济蹇之实功也。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：好运未来，宜谨守以待。</p><p>○　问战征：有险在前，未可进往，宜暂退守。</p><p>○　问营商：售卖之处，适有危，不可贩货前往，须暂时待价。</p><p>○　问功名：从军效力，皆冒险犯难，获邀奖赏，故曰“来誉”。</p><p>○　问家宅：地位险阻，迁居不利。</p><p>○　问疾病：在初起，不必急往求医，宜退而自养。</p><p>○　问婚姻：不必急就，还宜待。吉。</p><p>○　问失物：缓之可得。</p><p>○　问六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来，因一事进退未定，请卜以决之。筮得《蹇》之《既济》。</p><p>断曰：卦名曰《蹇》，《蹇》难也；卦爻在初，是初次遇难也。爻辞曰“往蹇”，其往就难地也；曰“来誉”，称其勇于赴难也。而《象传》则曰“宜待”，盖谓轻身尝试，不如待时而动也。玩释爻意，其于临难进退之机，历历明示。足下所问一事，为进退未定，得此爻而昭然如揭矣。神机发现，不爽毫厘，神妙如此。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“王”指九五，“臣”指六二，二居下卦之中，上应九五，爻互重《坎》，故曰“蹇蹇”，谓其涉《蹇》以济《蹇》，有鞠躬尽瘁之忱。诸爻皆言往，犹为国难而往赴之，二则直以国事为己事，犯其难而不顾也。《象传》以“终无尤”释之，谓其能致身事君，夫复何尤。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下气运尴尬，险难重重，主一身劳碌。</p><p>○　问战征：防军入险地，身被重围，有庞士元落凤坡之象。</p><p>○　问营商：为内地运货，中途被水，有人财两失之患。</p><p>○　问功名：为急公求名，名成而身莫保，邀身后之荣。</p><p>○　问家宅：此宅在艮山之中，向朝东北，险既重，不利。</p><p>○　问婚姻：二应五，主结贵亲；防后日夫君有难，身命难保。</p><p>○　问讼事：凶。</p><p>○　问行人：凶。</p><p>○　问失物：终不可得。</p><p>○　问六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十三年某月，予过访东京某绅士，互叙久别，主人曰：近因小儿为商务负债，日夕奔走措置，予甚忧虑。予曰：此等债务，忧亦无用，当善谋一置处之方，无已不如占问一卦，以决可否。于是主人自执筮蓍，予代为祈祷，筮得《蹇》之《井》。</p><p>断曰：《蹇》者多难之卦，二爻为下卦之主，是身任其难者也。令郎为商业负此巨债，不能不前往处理，无如债累重重，一时终不能了。今占得《蹇》二爻，爻辞曰“王臣蹇蹇，匪躬之故”，“蹇蹇”谓其事难而又难，“匪躬之故”，谓其债因商业而负，非一身之故也。玩前后爻象，三爻以“来返”为喜，知三爻不能相助为理；四爻曰“来连”，能与以为联手；五爻为卦之主，是营商正主，或成讼则为裁判长官，曰“朋来”，谓招集债友，共相商议。《象》曰“中节”，节省也，谓节减债款以了事。上六则为局外之长者，前来居向调剂也。据此现宜从初爻之辞，暂为退待，以俟机会，毋须劳碌。某绅士深感《易》之妙，后果如占所云。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三爻居内卦之上，为《艮》之主，当上下之交，与《坎》为邻。“往蹇”者，谓往赴五之“大蹇”。五以三阳当位，使之“来反”，以治其内。三本见险而止，喜退而不喜往也，其往也，为迫于诸爻，故同往；其返也，为得自全，故有喜。三动变为《比》，《比》二曰“比之自内”，故《象》以“内喜”释之。</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：运值多难，前进不利，不如退守。</p><p>○　问战征：有军出》旋师之象。</p><p>○　问营商：有去而不来，贩货复回，转销内地之象。</p><p>○　问功名：为出使在外，改为内用。</p><p>○　问家宅：此宅后靠山，前临水，初欲他迁，后复归来，得以团聚为喜。</p><p>○　问婚姻：前欲他适，后得归来，可喜。</p><p>○　问行人：即日来，喜。</p><p>○　问失物：失而复得。</p><p>○　问六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十三年，占国运，筮得《蹇》之《比》。</p><p>断曰：卦名曰《蹇》，《蹇》难也；爻曰“往蹇”，为往就蹇地；曰“来反”，为往而复返。《象》曰“内喜之也”，为喜其返而得以自全。详释爻辞，知国运值此多难，往而济蹇，不如返而治内。至五爻，大君擅权，朋来相辅，而蹇可济矣。则知以三济内蹇，以五济外蹇，相与有功也，喜可知矣。以爻象计之，应在二年之后。</p><p>明治元年四月，友人某来曰：余近奉仕官某藩之命，发程有期，特来告别。观其容貌威武，腰佩两刀，犹是藩士旧状，今际会风云，有志维新者也。请占前途气运，筮得《蹇》之《比》。</p><p>断曰：三为《艮》止之主，当上下之交，进退本多不决。其往也，固非所愿，亦第随人共往之耳；及其“来反”，焉得不中心喜之？爻辞之意如此。今足下因奉命将行，占得此爻，度足下之意，或有亦因前途有难，不喜前往。余劝足下，不妨准备前行，当有后命即来召回，欲令足下奉职于内也。后友人尚未起程，即命止行，留为内用。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四居上卦之首，比近于五，五所倚重，是为亲近之臣。“连”者，谓君臣一体，如心腹股肱之相联系也。“往蹇来连”，谓三与上为正应，故与上同往，最为联合，比初之往而有待，三之往而复反，较为得其实力也。《象》曰“当位实也”，四当位履正，《艮》为实，故曰“实”。上既比连尊爻，下又联络诸爻，得以实心实交以济蹇难也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：运多蹇险，以其能联合众心，得以济险。</p><p>○　问战征：四爻阴柔，可知军力单薄，以其能与众军同心同德，联络一气，乃可出险。</p><p>○　问功名：“来连”者，有连升之象。</p><p>○　问营商：“来连”者，谓先后商客，皆相连而来；曰“当位实也”，“实”，充实，谓得赢满也。</p><p>○　问家宅：此宅必与邻屋比连，地位相当，家道殷实。</p><p>○　问婚姻：必是老亲结亲，重联订好，吉。</p><p>○　问疾病：此病必连绵已久，一时不愈。</p><p>○　问讼事：迟久可了。</p><p>○　问行人：流连在外，一时不归。</p><p>○　问六甲：生男，想是孪胎。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>明治二十四年，有某友来，占某国枢密院气运，筮得《蹇》之《咸》。</p><p>断曰：四爻比连君位，是为亲近之臣，所谓心腹股肱，与君一气相联者也，恰合枢密院之位。足下占问某国，是外国也，故爻应在外卦。爻辞曰“往蹇，来连”，知某国近有内难外侮交作，枢密院诸臣，防有连累及祸者。诸爻皆曰“往蹇”，惟五与二不言往，五为大君，二为内臣，是身临其难者也。枢密院本在内臣之位，诸爻以图其济蹇，曰“往蹇”者，或指出使于外而言。一时蹇难未平，气运不佳，必待至上爻可以出蹇。</p><p>明治三十一年，占众议院气运，筮得《蹇》之《咸》。</p><p>断曰：爻曰“来连”，有联合众议之象；《象》曰“当位”，谓得当议员之位。今政府以战胜之后，受各邦之猜忌，将扩张兵备，预作济蹇之图，已呈出其议于议会，议员等联络私党，不应政府之意，政府因之多难。上卦为《坎》，坎险也，下卦为《艮》，《艮》止也，合之谓《蹇》，以致政府号令有阻止而不能行也。今占得四爻，四爻比近于五，知众议员中必有深浅时艰，能体合至尊之意，折衷众议之论说，以排解国家之困难，斯议可成，而蹇可济矣。《象》曰“当位实也”，“实”谓能实济其难，非从空言已也。当时议会自由改进，两党轧轹，议多不合，后自由党迎合政府之意，与国民协会联合，增税之议乃决。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>就诸爻言则为“往”，就五爻言则为“来”，在诸爻则《蹇》犹小，在五爻则《蹇》独大，盖五爻合诸爻之蹇以为《蹇》，而独当《蹇》之大者也，故曰“大蹇”。君臣以义合，朋友以情合，五略分言情，故喜其来而称之谓“朋”。五盈满当位，德足任人，故能使疏附后先，咸来辅翼，得藉群才以济“大蹇”。其济也，虽出于君之威福，而诸臣要与有力焉。五动体《坤》，《坤》“西南得朋”，“蹇利西南”，故亦曰“朋”。《象》以“中节”释之，谓五得位履中，不易其节，故卒得出蹇也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：厄运将退，渐得化危为安。</p><p>○　问战征：前既被围，今幸得救兵齐来，得以一战出围。</p><p>○　问功名：位近至尊，足以匡济，大荣，吉。</p><p>○　问营商：众货辐辏，一时难以脱售。</p><p>○　问家宅：地近禁卫，当冲击疲难之区，车马纷逐之会，不宜民居，可改作会馆议院。</p><p>○　问疾病：此是危难大症，宜集众医会治，方可望愈。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十年，占某贵显气运，筮得《蹇》之《谦》。</p><p>断曰：卦名曰《蹇》，爻曰“大蹇”，知《蹇》难重重，非一己之力，所能解脱。今某贵显占气运，得第五爻，五爻为《蹇》之主，其《蹇》愈大，其济愈难。幸某贵显德望素著，众心归服，得藉朋侪相助，乃能戡平大难。目下正当协力匡济之时，尚未出《蹇》，待一年后，《蹇》去《解》来，斯可平安无患。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻居《蹇》之极，躬处局外，本为《蹇》难所不及，爻曰“往蹇”，盖贤人君子，心切时艰，不敢以身不当位，置理乱于不闻也。“硕”，大也，“来硕”者，五得其相助为理，即以大任任之，如莘野渭滨之出而匡时者也，故曰“来硕”。《蹇》诸爻皆在蹇中，未尝言吉，至上爻，其《蹇》已终，故称“吉”。“大人”指五也，君臣同德，五爻以臣谓朋，上与五以君谓大人，盖即《彖传》所谓“利见大人，往有功也”。《象》以“志在内”释“来硕”，谓上之应在三，故“志在内也”。以“从贵”释“利见”，谓上之阴从阳，故曰“以从贵也”。</p><h2 id="上六占" tabindex="-1">上六占 <a class="header-anchor" href="#上六占" aria-label="Permalink to “上六占”">​</a></h2><p>○　问时运：现下大难已退，大运将来，可以出面求仕。</p><p>○　问战征：大兵已集，可以一战，以出重围。</p><p>○　问营商：众商咸来，货价大涨，即此脱售可复本，亦可获利。</p><p>○　问功名：文名大振，可以“利见大人”。</p><p>○　问家宅：此宅地位高大，灾煞已退，吉曜照临，且得贵人扶助。</p><p>○　问婚姻：主贵。</p><p>○　问讼事：须从大审院判结。</p><p>○　问六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某来，请占气运，筮得《蹇》之《渐》。</p><p>断曰：上爻居《蹇》之极，极则必变，将变《蹇》而成《解》，是大难将解之时也。今足下占气运，得上爻，爻辞曰“往蹇，来硕，吉，利见大人”，玩爻辞之意，谓“大蹇”已往，好运将来，吉无不利，且可往见大人，出而求仕，必得贵人提拔，仕途亨通。</p>',115)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
